import styles from "./calendar.module.less";
import { CurrencyHelper, DateHelper, LanguageHelper, multipleClassNames } from "@/core/helpers";
import { sv, enGB, nb } from "date-fns/locale";
import {
  ClassNames,
  DayPicker,
  DropdownProps,
  useDayPicker,
  DayButtonProps,
  DayProps,
  DayButton,
  WeekdaysProps,
  Weekdays,
  PropsRange,
} from "react-day-picker";
import { AnimatePresence, motion } from "framer-motion";
import dayjs from "dayjs";
import { CalendarProps, CommonDayPickerProps, RangeCalendarProps, SharedCalendarProps } from "./types/calendar-types";
import structure from "@/core/styling/structure.module.less";
import Icon from "@/core/components/primitives/icon/icon";
import { useTranslation } from "react-i18next";
import SelectBox, { SelectBoxOption } from "@/core/components/primitives/select-box/select-box";
import { PropsWithChildren, createContext, useContext } from "react";

// This context is used to pass data down to our custom components, as adding additional props either doesn't work, or causes unnecessary re-renders
const CalendarContext = createContext<Pick<SharedCalendarProps, "computedPriceMap" | "hasPriceLevelsWithMarking">>({});

const dayPickerClassNames: ClassNames = {
  ...styles,
  caption_label: styles.captionLabel,
  month_caption: styles.monthCaption,
  weekdays: styles.headRow,
  weekday: multipleClassNames(styles.headCell, "body-xs"),
  month_grid: styles.table,
  week: styles.row,
  day: styles.cell,
  day_button: multipleClassNames(styles.calendarDate, "body-s"),
  outside: styles.dayOutside,
};

function mapLocaleToDateFnsLocale(locale: string) {
  switch (locale) {
    default:
    case "sv":
      return sv;
    case "en":
      return enGB;
    case "nn":
      return nb;
  }
}

const NavigationArrow = ({
  onNavigate,
  targetMonth,
  icon,
  ariaLabel,
}: {
  onNavigate: (month: Date) => void;
  targetMonth: Date;
  icon: "chevron-right" | "chevron-left";
  ariaLabel: DropdownProps["aria-label"];
}) => {
  return (
    <button
      aria-label={ariaLabel}
      className={styles.navigationArrowButton}
      disabled={!targetMonth}
      type="button"
      onClick={() => onNavigate(targetMonth)}
    >
      <Icon name={icon} className={multipleClassNames(styles.navigationArrow, !targetMonth && styles.disabledIcon)} />
    </button>
  );
};

const MonthDropdown = (props: DropdownProps) => {
  const { onChange, value, name, options } = props;
  const { goToMonth, previousMonth, nextMonth } = useDayPicker();
  const { t } = useTranslation();

  const transformedOptions = options
    ?.filter((option) => !option.disabled)
    .map((option): SelectBoxOption => {
      return {
        value: option.value.toString(),
        label: option.label.charAt(0).toUpperCase() + option.label.slice(1),
      };
    });

  return (
    <div className={styles.navigationWrapper}>
      <NavigationArrow
        onNavigate={goToMonth}
        targetMonth={previousMonth as Date}
        icon="chevron-left"
        ariaLabel={t("previousMonth")}
      />
      <SelectBox
        options={transformedOptions}
        value={value?.toString()}
        onChange={(name, value) => {
          onChange && onChange({ target: { name, value } } as React.ChangeEvent<HTMLSelectElement>);
        }}
        name={name}
        className={styles.monthDropdownWrapper}
        shouldShowCheckIcon={false}
      />
      <NavigationArrow
        onNavigate={goToMonth}
        targetMonth={nextMonth as Date}
        icon="chevron-right"
        ariaLabel={t("nextMonth")}
      />
    </div>
  );
};

const CalendarHeader = (props: WeekdaysProps) => {
  const { t } = useTranslation();

  const { hasPriceLevelsWithMarking: showPriceIndicator } = useContext(CalendarContext);

  return (
    <>
      {showPriceIndicator && (
        <tbody>
          <tr className={styles.priceIndicatorRow}>
            <td className={styles.highlightIndicator}></td>
            <td className="p_tiny" data-contentful-label-id="calendarStepCalendarHeaderHighlightIndicator">
              {t("calendarStepCalendarHeaderHighlightIndicator")}
            </td>
          </tr>
        </tbody>
      )}
      {Weekdays(props)}
    </>
  );
};

const DayContentRenderer = (props: DayProps) => {
  const { hidden, outside } = props.modifiers;

  if (hidden && !outside) {
    return (
      <td className={multipleClassNames("body-l bold", styles.cell, styles.empty)}>
        {dayjs(props.day.date).get("date")}
      </td>
    );
  }
  return <td className={styles.cell} {...props} />;
};

const DayComponent = (props: DayButtonProps) => {
  const { computedPriceMap } = useContext(CalendarContext);
  const { showEventTick, isSoldOut, selected, range_middle, isFullyBooked, showMarking, clickableDisabled } =
    props.modifiers;

  // Retrieve the computed price using the day's date as key.
  const dayKey = DateHelper.toStringYYYYMMDD(props.day.date);
  const computedPrice = computedPriceMap?.get(dayKey)?.computedPrice;

  const wrapper = (children: PropsWithChildren["children"]) => (
    <DayButton
      {...props}
      className={multipleClassNames(
        "body-l bold",
        styles.calendarDate,
        isSoldOut && styles.isSoldOut,
        selected && styles.selected,
        showMarking && styles.marked,
        clickableDisabled && styles.clickableDisabled,
      )}
      translate="no"
    >
      {children}

      {isSoldOut && <div className={styles.unavailableMarker} />}

      {isFullyBooked && <div className={styles.isFullyBooked} />}

      {showEventTick && !selected && (
        <motion.span initial={{ top: "-2rem" }} animate={{ top: 0 }} className={styles.eventMarker} />
      )}
    </DayButton>
  );

  if (computedPrice !== undefined && !isSoldOut) {
    return wrapper(
      <div className={multipleClassNames("body-l bold", styles.dayWrapper)}>
        <span className={styles.scaleWhenSelected}>{props.children}</span>
        <AnimatePresence mode="popLayout" initial={false}>
          <motion.span
            key={computedPrice}
            className={multipleClassNames("body-xxs", styles.dayPrice)}
            initial={{ backgroundColor: "var(--foundation-color-primary-100)" }}
            animate={{ backgroundColor: "rgba(255, 255, 255, 0)" }}
            transition={{ duration: 0.5 }}
          >
            <span className={styles.scaleWhenSelected}>
              {/* Our currency helper adds a space between the number and the currency,
                which is not wanted in this case, when displaying the price in Swedish */}
              {CurrencyHelper.formatToSek(computedPrice).replace(/\s+kr$/, "kr")}
            </span>
          </motion.span>
        </AnimatePresence>
      </div>,
    );
  }

  if (selected || range_middle) {
    return wrapper(
      <motion.div
        key="selected"
        initial={{ scale: 0.7, opacity: 0.3 }}
        animate={{ scale: 1, opacity: 1 }}
        exit={{ scale: 0.7, opacity: 0.3 }}
        className={styles.selectedDateMarker}
      >
        {props.children}
      </motion.div>,
    );
  }

  return wrapper(<div className={multipleClassNames("body-l bold", styles.dayWrapper)}>{props.children} </div>);
};

const CalendarFooter = ({ value }: { value: string }) => (
  <div className={multipleClassNames("p_tiny", styles.footerText)}>{value}</div>
);

const CommonDayPicker = ({
  changedMonth,
  startDate,
  endDate,
  disabledDates,
  currentDisplayedMonth,
  animateEntry,
  modifiers,
  computedPriceMap,
  footerInfoString,
  hasPriceLevelsWithMarking = false,
  showOutsideDays = false,
  ...props
}: CommonDayPickerProps) => {
  const locale = LanguageHelper.currentLocale;
  const { t } = useTranslation();

  return (
    <motion.div
      className={styles.wrapper}
      key="calendar"
      initial={animateEntry ? { opacity: 0 } : false}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ duration: 0.3 }}
    >
      <CalendarContext.Provider value={{ computedPriceMap, hasPriceLevelsWithMarking }}>
        <DayPicker
          className={multipleClassNames(styles.innerWrapper, structure.blockMaxWidthS)}
          classNames={dayPickerClassNames}
          components={{
            Nav: () => <></>, // used to prevent the default navigation buttons from being rendered
            // NOTE: DO NOT USE ARROW FUNCTIONS OR ANONYMOUS FUNCTIONS HERE!
            // that would result in the component being re-mounted on each render, which causes some ugly animations
            MonthsDropdown: MonthDropdown,
            Weekdays: CalendarHeader,
            Day: DayContentRenderer,
            DayButton: DayComponent,
          }}
          formatters={{
            formatWeekdayName: (date) => DateHelper.toStringDD(date),
          }}
          {...props}
          labels={{
            labelDayButton: (date, modifiers) => {
              const labels = [DateHelper.toStringMMDDWeekday(date)];
              const { showEventTick, isSoldOut, selected, isFullyBooked } = modifiers;

              const computedPrice = computedPriceMap?.get(DateHelper.toStringYYYYMMDD(date))?.computedPrice;

              if (showEventTick) {
                labels.push(t("calendar.event"));
              }

              if (isSoldOut) {
                labels.push(t("soldOut"));
              } else if (computedPrice !== undefined) {
                labels.push(CurrencyHelper.formatToSek(computedPrice));
              }

              if (isFullyBooked) {
                labels.push(t("calendar.fullyBooked"));
              }
              if (selected) {
                labels.push(t("calendar.selected"));
              }

              return labels.join(", ");
            },
          }}
          modifiers={modifiers}
          disabled={disabledDates}
          footer={footerInfoString ? <CalendarFooter value={footerInfoString} /> : undefined}
          onMonthChange={changedMonth}
          month={currentDisplayedMonth}
          startMonth={startDate}
          endMonth={endDate}
          hidden={[{ before: startDate }, { after: endDate }]}
          required={false}
          captionLayout="dropdown-months"
          locale={mapLocaleToDateFnsLocale(locale)}
          showOutsideDays={showOutsideDays}
        />
      </CalendarContext.Provider>
    </motion.div>
  );
};

export const CalendarRange = ({
  selectedDates,
  changeDateRange,
  changedMonth,
  startDate = dayjs().toDate(),
  endDate = dayjs().endOf("month").toDate(),
  disabledDates,
  currentDisplayedMonth,
  resetIfRangeExists = false,
  animateEntry = false,
  modifiers = {},
}: RangeCalendarProps) => {
  if (currentDisplayedMonth && currentDisplayedMonth < startDate) {
    currentDisplayedMonth = startDate;
  }

  const handleRangeChange: PropsRange["onSelect"] = (newRange, clickedDate, modifiers, e) => {
    if (selectedDates?.to) newRange = { from: clickedDate };
    // since the newRange always has a to-date we have to override it if the selectedDates is undefined
    if (selectedDates === undefined) newRange = { from: clickedDate, to: undefined };

    changeDateRange?.(newRange, clickedDate, modifiers, e);
  };

  const dateChangeHandler = resetIfRangeExists ? handleRangeChange : changeDateRange;

  return (
    <CommonDayPicker
      changedMonth={changedMonth}
      startDate={startDate}
      endDate={endDate}
      disabledDates={disabledDates}
      currentDisplayedMonth={currentDisplayedMonth}
      animateEntry={animateEntry}
      modifiers={modifiers}
      selected={selectedDates}
      mode="range"
      onSelect={dateChangeHandler}
      // Leaving this here until we are sure we don't need it.
      // current only usercase for this component is First Camp and it shouldn't be implemented there.
      // excludeDisabled
    />
  );
};

const Calendar = ({
  selectedDate,
  changeDate,
  changedMonth,
  startDate = dayjs().toDate(),
  endDate = dayjs().toDate(),
  disabledDates,
  currentDisplayedMonth,
  animateEntry = false,
  modifiers = {},
  computedPriceMap,
  footerInfoString,
  hasPriceLevelsWithMarking,
  showOutsideDays,
}: CalendarProps) => {
  const handleDateChange = (date: Date) => {
    if (!DateHelper.isEqualYYYYMM(date, currentDisplayedMonth)) {
      changedMonth(date);
    }
    changeDate(date);
  };

  return (
    <CommonDayPicker
      changedMonth={changedMonth}
      startDate={startDate}
      endDate={endDate}
      disabledDates={disabledDates}
      currentDisplayedMonth={currentDisplayedMonth}
      animateEntry={animateEntry}
      modifiers={{
        ...modifiers,
        selected: selectedDate ?? false, // This is done in order to support the 2-day tickets at KDP
      }}
      mode="single"
      // Day Picker sets `date` to "undefined" if selected again. This `&&` prevents deselecting the date if the same day is already selected.
      onSelect={(date: Date | undefined) => date && handleDateChange(date)}
      computedPriceMap={computedPriceMap}
      footerInfoString={footerInfoString}
      hasPriceLevelsWithMarking={hasPriceLevelsWithMarking}
      showOutsideDays={showOutsideDays}
    />
  );
};

export default Calendar;
